const links = $json.notification_link || [];
const titles = $json.notification_title || [];

return links.map((link, index) => {
  const filename = String(link).split("/").pop();

  const match = filename.match(/ct(\d+)(?:h)?-(\d{4})\.pdf/i);

  return {
    json: {
      notification_link: link,
      notification_title: titles[index] || "",
      notification_filename: filename,
      notification_year: match ? Number(match[2]) : null,
      notification_number: match ? Number(match[1]) : null,
    }
  };
});
